/// \file
/// This file implements the targeting of the Machinelegalizer class for Z80.
/// \todo This should be generated by TableGen.
//===----------------------------------------------------------------------===//

#include "Z80LegalizerInfo.h"
#include "MCTargetDesc/Z80MCTargetDesc.h"
#include "Z80.h"
#include "Z80MachineFunctionInfo.h"
#include "Z80Subtarget.h"
#include "Z80TargetMachine.h"
#include "llvm/CodeGen/GlobalISel/GenericMachineInstrs.h"
#include "llvm/CodeGen/GlobalISel/LegalizerHelper.h"
#include "llvm/CodeGen/GlobalISel/MIPatternMatch.h"
#include "llvm/CodeGen/GlobalISel/MachineIRBuilder.h"
#include "llvm/CodeGen/MachineFrameInfo.h"
#include <functional>
#include <initializer_list>
using namespace llvm;
using namespace TargetOpcode;
using namespace LegalizeActions;
using namespace MIPatternMatch;

Z80LegalizerInfo::Z80LegalizerInfo(const Z80Subtarget &STI,
                                   const Z80TargetMachine &TM)
    : Subtarget(STI), TM(TM) {
  using namespace LegalityPredicates;
  using namespace LegalizeMutations;

  bool Is24Bit = Subtarget.is24Bit();
  LegalityPredicate pred24Bit = [=](const LegalityQuery &) { return Is24Bit; };

  LegalityPredicate predZ180Ops = [this](const LegalityQuery &) { return Subtarget.hasZ180Ops(); };

  std::array<LLT, 5> p;
  for (unsigned AddrSpace = 0; AddrSpace != p.size(); ++AddrSpace)
    p[AddrSpace] = LLT::pointer(AddrSpace, TM.getPointerSizeInBits(AddrSpace));
  LLT s1 = LLT::scalar(1);
  LLT s8 = LLT::scalar(8);
  LLT s16 = LLT::scalar(16);
  LLT s24 = LLT::scalar(24);
  LLT s32 = LLT::scalar(32);
  LLT s48 = LLT::scalar(48);
  LLT s64 = LLT::scalar(64);
  LLT sMax = Is24Bit ? s24 : s16;
  LLT sOther = Is24Bit ? s16 : s24;

  auto LegalTypes24 = {p[0], p[1], p[2], p[3], p[4], s8, s16, s24};
  auto LegalTypes16 = {p[0], p[1], p[2], p[3], p[4], s8, s16};
  auto LegalTypes = Is24Bit ? LegalTypes24 : LegalTypes16;
  auto LegalTypesOther = Is24Bit ? LegalTypes16 : LegalTypes24;
  auto LegalTypesWithOne24 = {p[0], p[1], p[2], p[3], p[4], s1, s8, s16, s24};
  auto LegalTypesWithOne16 = {p[0], p[1], p[2], p[3], p[4], s1, s8, s16};
  auto LegalTypesWithOne = Is24Bit ? LegalTypesWithOne24 : LegalTypesWithOne16;
  auto LegalScalars24 = {s8, s16, s24};
  auto LegalScalars16 = {s8, s16};
  auto LegalScalars = Is24Bit ? LegalScalars24 : LegalScalars16;
  auto LegalLargeScalars24 = {s32, s48, s64};
  auto LegalLargeScalars16 = {s32, s64};
  auto LegalLargeScalars = Is24Bit ? LegalLargeScalars24 : LegalLargeScalars16;
  auto LegalLibcallScalars24 = {s8, s16, s24, s32, s48, s64};
  auto LegalLibcallScalars16 = {s8, s16, s32, s64};
  auto LegalLibcallScalars =
      Is24Bit ? LegalLibcallScalars24 : LegalLibcallScalars16;
  auto NotMax24 = {s8, s16}, NotMax16 = {s8};
  auto NotMax = Is24Bit ? NotMax24 : NotMax16;
  auto NotMin24 = {s16, s24}, NotMin16 = {s16};
  auto NotMin = Is24Bit ? NotMin24 : NotMin16;
  auto NotMaxWithOne24 = {s1, s8, s16}, NotMaxWithOne16 = {s1, s8};
  auto NotMaxWithOne = Is24Bit ? NotMaxWithOne24 : NotMaxWithOne16;

  const auto IsSpecificType = [](unsigned TypeIdx, LLT Ty) {
    return
        [=](const LegalityQuery &Query) { return Query.Types[TypeIdx] == Ty; };
  };

  const auto IsScalarPointer = [](unsigned ScalarTypeIdx,
                                  unsigned PointerTypeIdx, auto Predicate) {
    return [=](const LegalityQuery &Query) {
      return Query.Types[ScalarTypeIdx].isScalar() &&
             Query.Types[PointerTypeIdx].isPointer() &&
             Predicate(Query.Types[ScalarTypeIdx].getSizeInBits(),
                       Query.Types[PointerTypeIdx].getSizeInBits());
    };
  };

  const auto ChangeToSameSizeScalar = [](unsigned TypeIdx,
                                         unsigned SizeTypeIdx) {
    return [=](const LegalityQuery &Query) {
      return std::make_pair(
          TypeIdx, LLT::scalar(Query.Types[SizeTypeIdx].getSizeInBits()));
    };
  };

  getActionDefinitionsBuilder(G_IMPLICIT_DEF)
      .legalFor(LegalTypesWithOne)
      .legalFor(LegalLargeScalars);

  getActionDefinitionsBuilder(G_MERGE_VALUES)
      .legalForCartesianProduct(NotMin, NotMax)
      // allow creating s32/s48/s64 from legal scalar sources (needed for libcall args)
      .legalForCartesianProduct(LegalLargeScalars, LegalScalars)
      // allow merging legal scalars into larger types (handles s72, s96, s128, etc.)
      .legalIf([=](const LegalityQuery &Q) {
        LLT DstTy = Q.Types[0];
        LLT SrcTy = Q.Types[1];
        if (!SrcTy.isScalar() || !DstTy.isScalar())
          return false;
        if (DstTy.getSizeInBits() % SrcTy.getSizeInBits() != 0)
          return false;
        unsigned SrcSize = SrcTy.getSizeInBits();
        return SrcSize == 8 || SrcSize == 16 || (Is24Bit && SrcSize == 24);
      })
      .customIf([=](const LegalityQuery &Q) {
        // custom legalize G_MERGE_VALUES when source type is s1, expand into shifts+ORs
        return Q.Types[1] == s1;
      })
      .clampScalar(0, *NotMin.begin(), *std::prev(NotMin.end()))
      .clampScalar(1, *NotMax.begin(), *std::prev(NotMax.end()));

  getActionDefinitionsBuilder(G_UNMERGE_VALUES)
      .legalForCartesianProduct(NotMax, NotMin)
      // allow splitting wide scalars into legal scalar parts (s32->s16, s48->s24, s64->s16)
      .legalForCartesianProduct(LegalScalars, LegalLargeScalars)
      // allow unmerging larger types into legal scalar parts (handles s72, s96, s128, etc.)
      .legalIf([=](const LegalityQuery &Q) {
        LLT DstTy = Q.Types[0];
        LLT SrcTy = Q.Types[1];
        if (!SrcTy.isScalar() || !DstTy.isScalar())
          return false;
        if (SrcTy.getSizeInBits() % DstTy.getSizeInBits() != 0)
          return false;
        unsigned DstSize = DstTy.getSizeInBits();
        return DstSize == 8 || DstSize == 16 || (Is24Bit && DstSize == 24);
      })
      .clampScalar(1, *NotMin.begin(), *std::prev(NotMin.end()))
      .clampScalar(0, *NotMax.begin(), *std::prev(NotMax.end()));

  getActionDefinitionsBuilder({G_EXTRACT, G_INSERT})
      .customForCartesianProduct(LegalLibcallScalars, LegalLibcallScalars)
      .unsupported();

  getActionDefinitionsBuilder({G_ZEXT, G_ANYEXT})
      .legalForCartesianProduct(LegalScalars, NotMaxWithOne)
      .clampScalar(0, *LegalScalars.begin(), *std::prev(LegalScalars.end()))
      .clampScalar(1, *NotMaxWithOne.begin(), *std::prev(NotMaxWithOne.end()));

  // sign extension:
  // - s1 -> sN is supported (result 0 or -1)
  // - also allow s8/s16 -> s16/s24 so instruction selection can emit
  //   proper SBC based sign fill and avoid broken sequences
  if (Is24Bit) {
    getActionDefinitionsBuilder(G_SEXT)
        .legalFor({{s8, s1},
                   {s16, s1},
                   {s24, s1},
                   {s16, s8},
                   {s24, s8},
                   {s24, s16},
                   {s32, s1},
                   {s32, s8},
                   {s32, s16},
                   {s32, s24},
                   {s48, s1},
                   {s48, s8},
                   {s48, s16},
                   {s48, s24},
                   {s48, s32},
                   {s64, s1},
                   {s64, s8},
                   {s64, s16},
                   {s64, s24},
                   {s64, s32},
                   {s64, s48}})
        .maxScalar(0, sMax);
  } else {
    getActionDefinitionsBuilder(G_SEXT)
        .legalFor({{s8, s1},
                   {s16, s1},
                   {s16, s8},
                   {s32, s1},
                   {s32, s8},
                   {s32, s16},
                   {s64, s1},
                   {s64, s8},
                   {s64, s16},
                   {s64, s32}})
        .maxScalar(0, sMax);
  }

  getActionDefinitionsBuilder(G_TRUNC)
      .legalForCartesianProduct(NotMaxWithOne, LegalScalars)
      .clampScalar(1, *LegalScalars.begin(), *std::prev(LegalScalars.end()))
      .clampScalar(0, *NotMaxWithOne.begin(), *std::prev(NotMaxWithOne.end()));

  getActionDefinitionsBuilder({G_FREEZE, G_PHI, G_CONSTANT})
      .legalFor(LegalTypes)
      .widenScalarToNextPow2(0, 8)
      .clampScalar(0, s8, sMax);

  getActionDefinitionsBuilder(G_FCONSTANT)
      .customFor({s32, s64});

  getActionDefinitionsBuilder(G_PTRTOINT)
      .legalIf(IsScalarPointer(0, 1, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(0, 1, std::less<>{}),
                     ChangeToSameSizeScalar(0, 1))
      .narrowScalarIf(IsScalarPointer(0, 1, std::greater<>{}),
                      ChangeToSameSizeScalar(0, 1));

  getActionDefinitionsBuilder({G_INTTOPTR, G_PTR_ADD})
      .legalIf(IsScalarPointer(1, 0, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(1, 0, std::less<>{}),
                     ChangeToSameSizeScalar(1, 0))
      .narrowScalarIf(IsScalarPointer(1, 0, std::greater<>{}),
                      ChangeToSameSizeScalar(1, 0));

  getActionDefinitionsBuilder(G_PTRMASK)
      .legalFor({p[2], s8})
      .customIf(IsScalarPointer(1, 0, std::equal_to<>{}))
      .widenScalarIf(IsScalarPointer(1, 0, std::less<>{}),
                     ChangeToSameSizeScalar(1, 0))
      .narrowScalarIf(IsScalarPointer(1, 0, std::greater<>{}),
                      ChangeToSameSizeScalar(1, 0));

  getActionDefinitionsBuilder({G_ADD, G_SUB})
      .legalFor({s8})
      .customFor(LegalLibcallScalars)
      .clampScalar(0, s8, sMax);

  getActionDefinitionsBuilder({G_UADDO, G_UADDE, G_USUBO, G_USUBE,
                               G_SADDO, G_SADDE, G_SSUBO, G_SSUBE})
      .legalForCartesianProduct(LegalScalars, {s1})
      .clampScalar(0, s8, sMax);

  getActionDefinitionsBuilder(G_MUL)
      .legalIf(all(predZ180Ops, typeIs(0, s8)))
      .libcallFor(LegalLibcallScalars)
      .widenScalarToNextPow2(0, 8)
      .minScalar(0, s8)
      .minScalar(0, s16)
      .minScalarIf(pred24Bit, 0, s24)
      .minScalar(0, s32)
      .minScalarIf(pred24Bit, 0, s48)
      .minScalar(0, s64)
      .maxScalar(0, s32);

  getActionDefinitionsBuilder({G_SDIV, G_UDIV, G_SREM, G_UREM})
      .libcallFor(LegalLibcallScalars)
      .clampScalar(0, s8, s32);

  getActionDefinitionsBuilder({G_AND, G_OR, G_XOR})
      .legalFor({s8})
      .customFor(LegalLibcallScalars)
      .clampScalar(0, s8, s32);

  getActionDefinitionsBuilder({G_SHL, G_LSHR, G_ASHR})
      .customForCartesianProduct(LegalLibcallScalars, {s8})
      .clampScalar(1, s8, s8)
      .widenScalarToNextPow2(0, 8)
      .minScalar(0, s8)
      .minScalar(0, s16)
      .minScalarIf(pred24Bit, 0, s24)
      .minScalar(0, s32)
      .minScalarIf(pred24Bit, 0, s48)
      .minScalar(0, s64)
      .maxScalar(0, s64);

  getActionDefinitionsBuilder({G_FSHL, G_FSHR, G_ROTR, G_ROTL, G_UMULO, G_SMULO,
                               G_UMULFIX, G_SMULFIX, G_SMULFIXSAT, G_UMULFIXSAT,
                               G_UDIVFIX, G_SDIVFIX, G_SDIVFIXSAT, G_UDIVFIXSAT,
                               G_FCANONICALIZE, G_MEMCPY, G_MEMCPY_INLINE,
                               G_MEMMOVE, G_MEMSET, G_BZERO})
      .custom();

  getActionDefinitionsBuilder({G_INTRINSIC_TRUNC,
                               G_INTRINSIC_ROUND,
                               G_INTRINSIC_ROUNDEVEN,
                               G_FADD,
                               G_FSUB,
                               G_FMUL,
                               G_FMA,
                               G_FMAD,
                               G_FDIV,
                               G_FREM,
                               G_FPOW,
                               G_FEXP,
                               G_FEXP2,
                               G_FLOG,
                               G_FLOG2,
                               G_FLOG10,
                               G_FNEG,
                               G_FABS,
                               G_FMINNUM,
                               G_FMAXNUM,
                               G_FCEIL,
                               G_FCOS,
                               G_FSIN,
                               G_FSQRT,
                               G_FFLOOR,
                               G_FRINT,
                               G_FNEARBYINT})
      .libcallFor({s32, s64});

  getActionDefinitionsBuilder({G_INTRINSIC_LRINT, G_LROUND})
      .libcallForCartesianProduct({s32}, {s32, s64});

  getActionDefinitionsBuilder({G_INTRINSIC_LLRINT, G_LLROUND})
      .libcallForCartesianProduct({s64}, {s32, s64});

  getActionDefinitionsBuilder(G_FPEXT).libcallFor({{s64, s32}});

  getActionDefinitionsBuilder(G_FPTRUNC).libcallFor({{s32, s64}});

  getActionDefinitionsBuilder({G_FPTOSI, G_FPTOUI})
      .libcallForCartesianProduct({s32, s64}, {s32, s64})
      .clampScalar(0, s32, s64);

  getActionDefinitionsBuilder({G_SITOFP, G_UITOFP})
      .libcallForCartesianProduct({s32, s64}, {s32, s64})
      .clampScalar(1, s32, s64);

  getActionDefinitionsBuilder(G_FCOPYSIGN).libcallFor({{s32, s32}, {s64, s64}});

  getActionDefinitionsBuilder(G_FFREXP).customFor({{s32, s24}, {s64, s24}});

  getActionDefinitionsBuilder(G_FLDEXP).customFor({{s32, s24}, {s64, s24}});

  getActionDefinitionsBuilder({G_LOAD, G_STORE})
      .legalForCartesianProduct(LegalTypes, {p[0]})
      .legalForCartesianProduct(LegalTypesOther, {p[1]})
      .legalForCartesianProduct({s8}, {p[2], p[3], p[4]})
      .minScalar(0, s8)
      .maxScalarIf(IsSpecificType(1, p[0]), 0, sMax)
      .maxScalarIf(IsSpecificType(1, p[1]), 0, sOther)
      .maxScalar(0, s8);
  for (unsigned MemOp : {G_LOAD, G_STORE})
    getLegacyLegalizerInfo().setLegalizeScalarToDifferentSizeStrategy(
        MemOp, 0, [](const LegacyLegalizerInfo::SizeAndActionsVec &Vec) {
          using namespace LegacyLegalizeActions;
          return LegacyLegalizerInfo::decreaseToSmallerTypesAndIncreaseToSmallest(
              Vec, NarrowScalar, WidenScalar);
        });

  getActionDefinitionsBuilder(
      {G_FRAME_INDEX, G_GLOBAL_VALUE, G_BRINDIRECT, G_JUMP_TABLE})
      .legalFor({p[0]});

  getActionDefinitionsBuilder(G_VASTART).customFor({p[0]});

  getActionDefinitionsBuilder(G_VAARG)
      .customForCartesianProduct(LegalLibcallScalars, {p[0]})
      .customForCartesianProduct({p[0], p[1], p[2], p[3], p[4]}, {p[0]})
      .clampScalar(0, s8, s64);

  getActionDefinitionsBuilder(G_ICMP)
      .legalForCartesianProduct({s1}, LegalTypes)
      .customForCartesianProduct({s1}, LegalLargeScalars)
      .clampScalar(1, s8, s64);

  getActionDefinitionsBuilder(G_FCMP)
      .customForCartesianProduct({s1}, {s32, s64});

  getActionDefinitionsBuilder(G_IS_FPCLASS)
      .lowerForCartesianProduct({s1}, {s32, s64});

  getActionDefinitionsBuilder(G_BRCOND)
      .legalFor({s1});
      

  getActionDefinitionsBuilder(G_BRJT)
      .legalForCartesianProduct({p[0]}, LegalScalars)
      .clampScalar(1, s8, sMax);

  getActionDefinitionsBuilder(G_SELECT)
      .legalForCartesianProduct(LegalTypes, {s1})
      .clampScalar(0, s8, sMax);

  getActionDefinitionsBuilder(
      {G_SDIVREM, G_UDIVREM, G_ABS, G_DYN_STACKALLOC, G_SEXT_INREG,
       G_SMULH, G_UMULH, G_SMIN, G_SMAX, G_UMIN, G_UMAX, G_UADDSAT, G_SADDSAT,
       G_USUBSAT, G_SSUBSAT, G_USHLSAT, G_SSHLSAT, G_FPOWI})
      .lower();

  getActionDefinitionsBuilder({G_CTTZ_ZERO_UNDEF, G_CTLZ_ZERO_UNDEF})
      .lowerForCartesianProduct({s8}, LegalLibcallScalars)
      .clampScalar(0, s8, s8);

  getActionDefinitionsBuilder({G_CTLZ, G_CTTZ})
      .customForCartesianProduct({s8}, LegalLibcallScalars)
      .clampScalar(0, s8, s8);

  getActionDefinitionsBuilder(G_CTPOP)
      .libcallForCartesianProduct({s8}, LegalLibcallScalars)
      .clampScalar(0, s8, s8);

  getActionDefinitionsBuilder(G_BSWAP)
      .legalFor({s16})
      .libcallFor(LegalLargeScalars)
      .clampScalar(0, s16, s64);

  getActionDefinitionsBuilder(G_BITREVERSE)
      .libcallFor(LegalLibcallScalars)
      .clampScalar(0, s8, s64);

  getLegacyLegalizerInfo().computeTables();
  verify(*STI.getInstrInfo());
}

bool Z80LegalizerInfo::legalizeCustom(
    LegalizerHelper &Helper, MachineInstr &MI,
    LostDebugLocObserver &LocObserver) const {
  auto handleResult = [](LegalizerHelper::LegalizeResult Result) {
    return Result != LegalizerHelper::UnableToLegalize;
  };

  Helper.MIRBuilder.setInstrAndDebugLoc(MI);
  switch (MI.getOpcode()) {
  default:
    // No idea what to do.
    return false;
  case G_ADD:
  case G_SUB:
    return handleResult(legalizeAddSub(Helper, MI, LocObserver));
  case G_AND:
  case G_OR:
  case G_XOR:
  case G_PTRMASK:
    return handleResult(legalizeBitwise(Helper, MI, LocObserver));
  case G_SEXT:
    return handleResult(legalizeSExt(Helper, MI, LocObserver));
  case G_EXTRACT:
  case G_INSERT:
    return handleResult(legalizeExtractInsert(Helper, MI));
  case G_FCONSTANT:
    return handleResult(legalizeFConstant(Helper, MI));
  case G_VASTART:
    return handleResult(legalizeVAStart(Helper, MI));
  case G_VAARG:
    return handleResult(legalizeVAArg(Helper, MI));
  case G_SHL:
  case G_LSHR:
  case G_ASHR:
    return handleResult(legalizeShift(Helper, MI, LocObserver));
  case G_FSHL:
  case G_FSHR:
  case G_ROTR:
  case G_ROTL:
    return handleResult(legalizeFunnelShift(Helper, MI));
  case G_ICMP:
  case G_FCMP:
    return handleResult(legalizeCompare(Helper, MI, LocObserver));
  case G_UMULO:
  case G_SMULO:
    return handleResult(legalizeMultiplyWithOverflow(Helper, MI, LocObserver));
  case G_SMULFIX:
  case G_UMULFIX:
  case G_SMULFIXSAT:
  case G_UMULFIXSAT:
    return handleResult(legalizeFixedMultiply(Helper, MI));
  case G_SDIVFIX:
  case G_UDIVFIX:
  case G_SDIVFIXSAT:
  case G_UDIVFIXSAT:
    return handleResult(legalizeFixedDivide(Helper, MI));
  case G_FCANONICALIZE:
    return handleResult(legalizeFCanonicalize(Helper, MI));
  case G_FFREXP:
    return handleResult(legalizeFFrexp(Helper, MI, LocObserver));
  case G_FLDEXP:
    return handleResult(legalizeFLdexp(Helper, MI, LocObserver));
  case G_CTLZ:
  case G_CTTZ:
    return handleResult(legalizeCtz(Helper, MI, LocObserver));
  case G_MEMCPY:
  case G_MEMCPY_INLINE:
  case G_MEMMOVE:
  case G_MEMSET:
  case G_BZERO:
    return handleResult(legalizeMemIntrinsic(Helper, MI, LocObserver));
  case G_MERGE_VALUES:
    return handleResult(legalizeMergeValues(Helper, MI));
  }
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeAddSub(LegalizerHelper &Helper, MachineInstr &MI,
                                 LostDebugLocObserver &LocObserver) const {
  assert((MI.getOpcode() == G_ADD || MI.getOpcode() == G_SUB) &&
         "Unexpected opcode");
  Function &F = Helper.MIRBuilder.getMF().getFunction();
  MachineRegisterInfo &MRI = *Helper.MIRBuilder.getMRI();
  Register DstReg = MI.getOperand(0).getReg();
  LLT LLTy = MRI.getType(DstReg);
  unsigned Size = LLTy.getSizeInBits();
  bool LegalSize = Size == 16 || (Subtarget.is24Bit() && Size == 24);
  Register LHSReg;
  if (mi_match(MI, MRI, m_Neg(m_Reg(LHSReg)))) {
    if (!F.hasOptSize() && LegalSize)
      return LegalizerHelper::Legalized;
    auto &Ctx = F.getContext();
    RTLIB::Libcall Libcall;
    switch (Size) {
    case 16:
      Libcall = RTLIB::NEG_I16;
      break;
    case 24:
      Libcall = RTLIB::NEG_I24;
      break;
    case 32:
      Libcall = RTLIB::NEG_I32;
      break;
    case 48:
      Libcall = RTLIB::NEG_I48;
      break;
    case 64:
      Libcall = RTLIB::NEG_I64;
      break;
    default:
      llvm_unreachable("Unexpected type");
    }
    Type *Ty = IntegerType::get(Ctx, Size);
    auto Result = createLibcall(Helper.MIRBuilder, Libcall, {DstReg, Ty, 0},
                                {{LHSReg, Ty, 0}}, LocObserver, &MI);
    MI.eraseFromParent();
    return Result;
  }
  if (LegalSize)
    return LegalizerHelper::Legalized;
  if (Subtarget.is24Bit() && Size == 48)
    return Helper.narrowScalar(MI, 0, LLT::scalar(24));
  return Helper.libcall(MI, LocObserver);
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeBitwise(LegalizerHelper &Helper, MachineInstr &MI,
                                  LostDebugLocObserver &LocObserver) const {
  assert((MI.getOpcode() == G_AND || MI.getOpcode() == G_OR ||
          MI.getOpcode() == G_XOR || MI.getOpcode() == G_PTRMASK) &&
         "Unexpected opcode");
  Function &F = Helper.MIRBuilder.getMF().getFunction();
  bool OptSize = F.hasOptSize();
  MachineRegisterInfo &MRI = *Helper.MIRBuilder.getMRI();
  Register DstReg = MI.getOperand(0).getReg();
  unsigned Size = MRI.getType(DstReg).getSizeInBits();
  if (!OptSize && Size == 16)
    if (Helper.narrowScalar(MI, 0, LLT::scalar(8)) ==
        LegalizerHelper::Legalized)
      return LegalizerHelper::Legalized;
  Register LHSReg;
  if (mi_match(MI, MRI, m_Not(m_Reg(LHSReg)))) {
    if (!OptSize && (Size == 16 || (Subtarget.is24Bit() && Size == 24))) {
      Helper.MIRBuilder.buildSub(
          DstReg, Helper.MIRBuilder.buildConstant(LLT::scalar(Size), -1),
          MI.getOperand(1).getReg());
      MI.eraseFromParent();
      return LegalizerHelper::Legalized;
    }
    auto &Ctx = F.getContext();
    RTLIB::Libcall Libcall;
    switch (Size) {
    default: llvm_unreachable("Unexpected type");
    case 16: Libcall = RTLIB::NOT_I16; break;
    case 24: Libcall = RTLIB::NOT_I24; break;
    case 32: Libcall = RTLIB::NOT_I32; break;
    case 48: Libcall = RTLIB::NOT_I48; break;
    case 64: Libcall = RTLIB::NOT_I64; break;
    }
    Type *Ty = IntegerType::get(Ctx, Size);
    auto Result = createLibcall(Helper.MIRBuilder, Libcall, {DstReg, Ty, 0},
                                {{LHSReg, Ty, 0}}, LocObserver, &MI);
    MI.eraseFromParent();
    return Result;
  }
  if (MI.getOpcode() == G_PTRMASK) {
    auto &Ctx = F.getContext();
    RTLIB::Libcall Libcall;
    switch (Size) {
    default: llvm_unreachable("Unexpected type");
    case 16: Libcall = RTLIB::AND_I16; break;
    case 24: Libcall = RTLIB::AND_I24; break;
    case 32: Libcall = RTLIB::AND_I32; break;
    case 48: Libcall = RTLIB::AND_I48; break;
    case 64: Libcall = RTLIB::AND_I64; break;
    }
    Type *Ty = IntegerType::get(Ctx, Size);
    auto Result = createLibcall(Helper.MIRBuilder, Libcall, {DstReg, Ty, 0},
                                {{MI.getOperand(1).getReg(), Ty, 0},
                                 {MI.getOperand(2).getReg(), Ty, 1}},
                                LocObserver, &MI);
    MI.eraseFromParent();
    return Result;
  }
  return Helper.libcall(MI, LocObserver);
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeSExt(LegalizerHelper &Helper, MachineInstr &MI,
                               LostDebugLocObserver &LocObserver) const {
  assert(MI.getOpcode() == G_SEXT && "Unexpected opcode");

  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
  Register DstReg = MI.getOperand(0).getReg();
  Register SrcReg = MI.getOperand(1).getReg();
  LLT DstTy = MRI.getType(DstReg);
  LLT SrcTy = MRI.getType(SrcReg);
  unsigned DstSize = DstTy.getSizeInBits();

  const bool Is24Bit = Subtarget.is24Bit();

  auto buildAShrSignFill = [&](LLT Ty, Register Val) {
    const unsigned Bits = Ty.getSizeInBits();
    Register Amt = MIRBuilder.buildConstant(LLT::scalar(8), Bits - 1).getReg(0);
    return MIRBuilder.buildAShr(Ty, Val, Amt).getReg(0);
  };

  if (!Is24Bit) {
    // 16 bit mode: build sign fill from the high 16-bit chunk (or the extended
    // source for <=16-bit values)
    LLT s16 = LLT::scalar(16);

    auto sextTo16 = [&](Register V) {
      if (MRI.getType(V) == s16)
        return V;
      return MIRBuilder.buildSExt(s16, V).getReg(0);
    };

    const unsigned SrcSize = SrcTy.getSizeInBits();
    if (DstSize == 32) {
      Register Lo16 = (SrcSize <= 16) ? sextTo16(SrcReg)
                                      : MRI.createGenericVirtualRegister(s16);
      Register Hi16 = MRI.createGenericVirtualRegister(s16);
      if (SrcSize == 32) {
        MIRBuilder.buildUnmerge({Lo16, Hi16}, SrcReg);
      } else if (SrcSize <= 16) {
        Hi16 = buildAShrSignFill(s16, Lo16);
      } else {
        return LegalizerHelper::UnableToLegalize;
      }
      if (SrcSize <= 16)
        MIRBuilder.buildMergeLikeInstr(DstReg, {Lo16, Hi16});
      else
        MIRBuilder.buildMergeLikeInstr(DstReg, {Lo16, Hi16});
    } else if (DstSize == 64) {
      if (SrcSize <= 16) {
        Register Ext16 = sextTo16(SrcReg);
        Register SignFill16 = buildAShrSignFill(s16, Ext16);
        MIRBuilder.buildMergeLikeInstr(DstReg,
                                       {Ext16, SignFill16, SignFill16,
                                        SignFill16});
      } else if (SrcSize == 32) {
        Register Lo16 = MRI.createGenericVirtualRegister(s16);
        Register Hi16 = MRI.createGenericVirtualRegister(s16);
        MIRBuilder.buildUnmerge({Lo16, Hi16}, SrcReg);
        Register SignFill16 = buildAShrSignFill(s16, Hi16);
        MIRBuilder.buildMergeLikeInstr(DstReg,
                                       {Lo16, Hi16, SignFill16, SignFill16});
      } else {
        return LegalizerHelper::UnableToLegalize;
      }
    } else {
      return LegalizerHelper::UnableToLegalize;
    }

    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  // 24 bit mode
  LLT s8 = LLT::scalar(8);
  LLT s16 = LLT::scalar(16);
  LLT s24 = LLT::scalar(24);

  auto sextTo24 = [&](Register V) {
    if (MRI.getType(V) == s24)
      return V;
    return MIRBuilder.buildSExt(s24, V).getReg(0);
  };

  const unsigned SrcSize = SrcTy.getSizeInBits();

  if (DstSize == 32) {
    if (SrcSize == 32) {
      MIRBuilder.buildCopy(DstReg, SrcReg);
      MI.eraseFromParent();
      return LegalizerHelper::Legalized;
    }

    if (SrcSize > 24)
      return LegalizerHelper::UnableToLegalize;

    Register Ext24 = sextTo24(SrcReg);
    LLVMContext &Ctx = MIRBuilder.getMF().getFunction().getContext();
    Type *DstIRTy = IntegerType::get(Ctx, 32);
    Type *ArgIRTy = IntegerType::get(Ctx, 24);
    auto Result =
        createLibcall(MIRBuilder, RTLIB::SEXT_I24_I32, {DstReg, DstIRTy, 0},
                      {{Ext24, ArgIRTy, 0}}, LocObserver, &MI);
    MI.eraseFromParent();
    return Result;
  }

  if (DstSize == 48) {
    if (SrcSize <= 24) {
      Register Ext24 = sextTo24(SrcReg);
      Register SignFill24 = buildAShrSignFill(s24, Ext24);
      MIRBuilder.buildMergeLikeInstr(DstReg, {Ext24, SignFill24});
    } else if (SrcSize == 32) {
      Register Lo24 = MRI.createGenericVirtualRegister(s24);
      MIRBuilder.buildInstr(G_EXTRACT, {Lo24}, {SrcReg}).addImm(0);
      Register Hi8 = MRI.createGenericVirtualRegister(s8);
      MIRBuilder.buildInstr(G_EXTRACT, {Hi8}, {SrcReg}).addImm(24);

      Register SignFill16 = MIRBuilder.buildSExt(s16, Hi8).getReg(0);
      Register Hi8Z = MIRBuilder.buildZExt(s24, Hi8).getReg(0);
      Register SF24 = MIRBuilder.buildZExt(s24, SignFill16).getReg(0);
      Register ShAmt = MIRBuilder.buildConstant(s8, 8).getReg(0);
      Register SFShift = MIRBuilder.buildShl(s24, SF24, ShAmt).getReg(0);
      Register Mid24 = MIRBuilder.buildOr(s24, Hi8Z, SFShift).getReg(0);
      MIRBuilder.buildMergeLikeInstr(DstReg, {Lo24, Mid24});
    } else if (SrcSize == 48) {
      MIRBuilder.buildCopy(DstReg, SrcReg);
    } else {
      return LegalizerHelper::UnableToLegalize;
    }

    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  if (DstSize == 64) {
    if (SrcSize <= 24) {
      Register Ext24 = sextTo24(SrcReg);
      Register SignFill24 = buildAShrSignFill(s24, Ext24);
      Register SignFill16 = MIRBuilder.buildTrunc(s16, SignFill24).getReg(0);
      auto Seq = MIRBuilder.buildInstr(TargetOpcode::REG_SEQUENCE, {DstReg}, {});
      Seq.addUse(Ext24).addImm(Z80::sub_low24);
      Seq.addUse(SignFill24).addImm(Z80::sub_mid24);
      Seq.addUse(SignFill16).addImm(Z80::sub_word3);
    } else if (SrcSize == 32) {
      Register Lo24 = MRI.createGenericVirtualRegister(s24);
      MIRBuilder.buildInstr(G_EXTRACT, {Lo24}, {SrcReg}).addImm(0);
      Register Hi8 = MRI.createGenericVirtualRegister(s8);
      MIRBuilder.buildInstr(G_EXTRACT, {Hi8}, {SrcReg}).addImm(24);

      Register SignFill16 = MIRBuilder.buildSExt(s16, Hi8).getReg(0);
      Register Hi8Z = MIRBuilder.buildZExt(s24, Hi8).getReg(0);
      Register SF24 = MIRBuilder.buildZExt(s24, SignFill16).getReg(0);
      Register ShAmt = MIRBuilder.buildConstant(s8, 8).getReg(0);
      Register SFShift = MIRBuilder.buildShl(s24, SF24, ShAmt).getReg(0);
      Register Mid24 = MIRBuilder.buildOr(s24, Hi8Z, SFShift).getReg(0);
      auto Seq = MIRBuilder.buildInstr(TargetOpcode::REG_SEQUENCE, {DstReg}, {});
      Seq.addUse(Lo24).addImm(Z80::sub_low24);
      Seq.addUse(Mid24).addImm(Z80::sub_mid24);
      Seq.addUse(SignFill16).addImm(Z80::sub_word3);
    } else if (SrcSize == 48) {
      Register Lo24 = MRI.createGenericVirtualRegister(s24);
      Register Mid24 = MRI.createGenericVirtualRegister(s24);
      MIRBuilder.buildUnmerge({Lo24, Mid24}, SrcReg);
      Register SignFill24 = buildAShrSignFill(s24, Mid24);
      Register SignFill16 = MIRBuilder.buildTrunc(s16, SignFill24).getReg(0);
      auto Seq = MIRBuilder.buildInstr(TargetOpcode::REG_SEQUENCE, {DstReg}, {});
      Seq.addUse(Lo24).addImm(Z80::sub_low24);
      Seq.addUse(Mid24).addImm(Z80::sub_mid24);
      Seq.addUse(SignFill16).addImm(Z80::sub_word3);
    } else if (SrcSize == 64) {
      MIRBuilder.buildCopy(DstReg, SrcReg);
    } else {
      return LegalizerHelper::UnableToLegalize;
    }

    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  return LegalizerHelper::UnableToLegalize;
}


LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeExtractInsert(LegalizerHelper &Helper,
                                        MachineInstr &MI) const {
  assert((MI.getOpcode() == G_EXTRACT || MI.getOpcode() == G_INSERT) &&
         "Unexpected opcode");
  return MI.getOperand(MI.getNumExplicitOperands() - 1).getImm() & 7
             ? LegalizerHelper::UnableToLegalize
             : LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFConstant(LegalizerHelper &Helper,
                                    MachineInstr &MI) const {
  assert(MI.getOpcode() == G_FCONSTANT && "Unexpected opcode");
  auto *FPImm = MI.getOperand(1).getFPImm();
  auto AsInteger = FPImm->getValueAPF().bitcastToAPInt();
  Helper.MIRBuilder.buildConstant(MI.getOperand(0), *ConstantInt::get(
                                                         FPImm->getContext(),
                                                         AsInteger));
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeVAStart(LegalizerHelper &Helper,
                                  MachineInstr &MI) const {
  assert(MI.getOpcode() == G_VASTART && "Unexpected opcode");
  MachineFunction &MF = Helper.MIRBuilder.getMF();
  Z80MachineFunctionInfo &FuncInfo = *MF.getInfo<Z80MachineFunctionInfo>();
  int FrameIdx = FuncInfo.getVarArgsFrameIndex();
  assert(FrameIdx && "Found va_start but never setVarArgsFrameIndex!");
  LLT p0 = LLT::pointer(0, TM.getPointerSizeInBits(0));
  Helper.MIRBuilder.buildStore(Helper.MIRBuilder.buildFrameIndex(p0, FrameIdx),
                               MI.getOperand(0).getReg(),
                               *MI.memoperands().front());
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeVAArg(LegalizerHelper &Helper,
                                MachineInstr &MI) const {
  assert(MI.getOpcode() == G_VAARG && "Unexpected opcode");
  
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineFunction &MF = MIRBuilder.getMF();
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
  
  // G_VAARG operands:
  // %dst = G_VAARG %list_ptr, alignment
  Register DstReg = MI.getOperand(0).getReg();
  Register ListPtr = MI.getOperand(1).getReg();
  
  // alignment from G_VAARG can be 0 or not power of 2, use 1 as default
  uint64_t AlignVal = MI.getOperand(2).getImm();
  Align Alignment = (AlignVal && llvm::isPowerOf2_64(AlignVal)) 
                    ? Align(AlignVal) : Align(1);
  
  LLT PtrTy = MRI.getType(ListPtr);
  LLT ValTy = MRI.getType(DstReg);

  const unsigned PtrSize = (PtrTy.getSizeInBits() + 7) / 8;  // round up to bytes
  const Align PtrAlign = Align(1);
  
  // load the current va_list pointer value
  auto List = MIRBuilder.buildLoad(
      PtrTy, ListPtr,
      *MF.getMachineMemOperand(MachinePointerInfo(), MachineMemOperand::MOLoad,
                               PtrTy, PtrAlign));
  
  // handle alignment if needed (Z80 typically doesn't need this, but be safe)
  MachineInstrBuilder ArgPtr;
  if (Alignment > PtrAlign) {
    // realign the list to the actual required alignment
    LLT IntPtrTy = LLT::scalar(PtrTy.getSizeInBits());
    auto AlignMinus1 = MIRBuilder.buildConstant(IntPtrTy, Alignment.value() - 1);
    auto ListTmp = MIRBuilder.buildPtrAdd(PtrTy, List, AlignMinus1.getReg(0));
    // mask off the low bits to align
    auto AlignMask = MIRBuilder.buildConstant(IntPtrTy, ~(Alignment.value() - 1));
    auto ListInt = MIRBuilder.buildPtrToInt(IntPtrTy, ListTmp);
    auto AlignedInt = MIRBuilder.buildAnd(IntPtrTy, ListInt, AlignMask);
    ArgPtr = MIRBuilder.buildIntToPtr(PtrTy, AlignedInt);
  } else {
    ArgPtr = List;
  }
  
  // load the actual argument value from the va_list pointer
  uint64_t ValSize = ValTy.getSizeInBits() / 8;
  MIRBuilder.buildLoad(
      DstReg, ArgPtr,
      *MF.getMachineMemOperand(MachinePointerInfo(), MachineMemOperand::MOLoad,
                               ValTy, std::max(Alignment, PtrAlign)));
  
  // calculate the new va_list pointer (advance by pointer-size-aligned value size)
  LLT IntPtrTy = LLT::scalar(PtrTy.getSizeInBits());
  auto Size = MIRBuilder.buildConstant(IntPtrTy, alignTo(ValSize, PtrSize));
  auto NewList = MIRBuilder.buildPtrAdd(PtrTy, ArgPtr, Size.getReg(0));
  
  // store the updated pointer back to va_list
  MIRBuilder.buildStore(NewList, ListPtr,
                        *MF.getMachineMemOperand(MachinePointerInfo(),
                                                 MachineMemOperand::MOStore,
                                                 PtrTy, PtrAlign));
  
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeShift(LegalizerHelper &Helper, MachineInstr &MI,
                                LostDebugLocObserver &LocObserver) const {
  unsigned Opc = MI.getOpcode();
  assert((Opc == G_SHL || Opc == G_LSHR || Opc == G_ASHR) &&
         "Unexpected opcode");
  MachineRegisterInfo &MRI = *Helper.MIRBuilder.getMRI();
  Register DstReg = MI.getOperand(0).getReg();
  LLT Ty = MRI.getType(DstReg);
  if (auto Amt =
          getIConstantVRegValWithLookThrough(MI.getOperand(2).getReg(), MRI)) {
    if (Ty == LLT::scalar(8) && Amt->Value == 1)
      return LegalizerHelper::AlreadyLegal;
    // s16/s24 left shift by 1-6 can use inline ADD instructions
    // library call is 7-8 bytes (ld bc, N + call __ishl), so up to 6 adds is optimal
    if (Opc == G_SHL && Amt->Value.uge(1) && Amt->Value.ule(6)) {
      unsigned TySize = Ty.getSizeInBits();
      if (TySize == 16 || (Subtarget.is24Bit() && TySize == 24))
        return LegalizerHelper::AlreadyLegal;
    }
    if ((Opc == G_SHL || Opc == G_LSHR) && Ty == LLT::scalar(16) &&
        Amt->Value == 8)
      return LegalizerHelper::AlreadyLegal;
    if (Opc == G_ASHR && Amt->Value == Ty.getSizeInBits() - 1 &&
        (Ty == LLT::scalar(8) || Ty == LLT::scalar(16) ||
         (Subtarget.is24Bit() && Ty == LLT::scalar(24))))
      return LegalizerHelper::AlreadyLegal;
    if (Opc == G_LSHR && Subtarget.is24Bit() &&
        Ty == LLT::scalar(24) && Amt->Value == 23)
      return LegalizerHelper::AlreadyLegal;
  }
  return Helper.libcall(MI, LocObserver);
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFunnelShift(LegalizerHelper &Helper,
                                      MachineInstr &MI) const {
  unsigned Opc = MI.getOpcode(); 
  assert((Opc == G_FSHL || Opc == G_FSHR || Opc == G_ROTR || Opc == G_ROTL) &&
         "Unexpected opcode");

  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  Register DstReg = MI.getOperand(0).getReg();
  Register FwdReg = MI.getOperand(1).getReg();
  Register RevReg = MI.getOperand(MI.getNumExplicitOperands() - 2).getReg();
  Register AmtReg = MI.getOperand(MI.getNumExplicitOperands() - 1).getReg();

  LLT Ty = MRI.getType(DstReg);
  unsigned BW = Ty.getSizeInBits();
  LLT ShTy = MRI.getType(AmtReg);
  // Amt & (BW - 1) is only equivalent to modulo when
  // bw is a power of two
  if ((BW & (BW - 1)) != 0) {
    Register ShAmtReg;
    if (auto AmtC = getIConstantVRegValWithLookThrough(AmtReg, MRI)) {
      ShAmtReg = MIRBuilder.buildConstant(ShTy, AmtC->Value.urem(BW)).getReg(0);
    } else {
      MachineInstr *AmtDef = MRI.getVRegDef(AmtReg);
      if (!AmtDef) {
        if (Opc == G_ROTR || Opc == G_ROTL)
          return Helper.lowerRotate(MI);
        return Helper.lowerFunnelShift(MI);
      }
      unsigned AmtOpc = AmtDef->getOpcode();
      if (AmtOpc != G_UREM && AmtOpc != G_SREM) {
        if (Opc == G_ROTR || Opc == G_ROTL)
          return Helper.lowerRotate(MI);
        return Helper.lowerFunnelShift(MI);
      }

      auto DivC = getIConstantVRegValWithLookThrough(AmtDef->getOperand(2).getReg(),
                                                     MRI);
      if (!DivC || DivC->Value != BW) {
        if (Opc == G_ROTR || Opc == G_ROTL)
          return Helper.lowerRotate(MI);
        return Helper.lowerFunnelShift(MI);
      }

      if (AmtOpc == G_UREM) {
        ShAmtReg = AmtReg;
      } else {
        auto Zero = MIRBuilder.buildConstant(ShTy, 0);
        auto BWConst = MIRBuilder.buildConstant(ShTy, BW);
        auto IsNeg =
            MIRBuilder.buildICmp(CmpInst::ICMP_SLT, LLT::scalar(1), AmtReg, Zero);
        auto AddBW = MIRBuilder.buildAdd(ShTy, AmtReg, BWConst);
        ShAmtReg = MIRBuilder.buildSelect(ShTy, IsNeg, AddBW, AmtReg).getReg(0);
      }
    }

    bool IsFSHL = Opc == G_FSHL || Opc == G_ROTL;
    Register XReg = MI.getOperand(1).getReg();
    Register YReg = MI.getOperand(MI.getNumExplicitOperands() - 2).getReg();

    if (auto ShAmtC = getIConstantVRegValWithLookThrough(ShAmtReg, MRI)) {
      unsigned C = ShAmtC->Value.urem(BW);
      if (C == 0) {
        MIRBuilder.buildCopy(DstReg, IsFSHL ? XReg : YReg);
        MI.eraseFromParent();
        return LegalizerHelper::Legalized;
      }

      auto ShC = MIRBuilder.buildConstant(ShTy, C);
      auto InvShC = MIRBuilder.buildConstant(ShTy, BW - C);
      Register ShXReg, ShYReg;
      if (IsFSHL) {
        ShXReg = MIRBuilder.buildShl(Ty, XReg, ShC).getReg(0);
        ShYReg = MIRBuilder.buildLShr(Ty, YReg, InvShC).getReg(0);
      } else {
        ShXReg = MIRBuilder.buildShl(Ty, XReg, InvShC).getReg(0);
        ShYReg = MIRBuilder.buildLShr(Ty, YReg, ShC).getReg(0);
      }
      MIRBuilder.buildOr(DstReg, ShXReg, ShYReg);
      MI.eraseFromParent();
      return LegalizerHelper::Legalized;
    }

    // fshl: (X << C) | (Y >> 1 >> ((BW - 1) - C))
    // fshr: (X << 1 << ((BW - 1) - C)) | (Y >> C)
    auto BWMinus1 = MIRBuilder.buildConstant(ShTy, BW - 1);
    auto InvShAmtReg = MIRBuilder.buildSub(ShTy, BWMinus1, ShAmtReg);
    auto One = MIRBuilder.buildConstant(ShTy, 1);

    Register ShXReg, ShYReg;
    if (IsFSHL) {
      ShXReg = MIRBuilder.buildShl(Ty, XReg, ShAmtReg).getReg(0);
      auto ShY1Reg = MIRBuilder.buildLShr(Ty, YReg, One);
      ShYReg = MIRBuilder.buildLShr(Ty, ShY1Reg, InvShAmtReg).getReg(0);
    } else {
      auto ShX1Reg = MIRBuilder.buildShl(Ty, XReg, One);
      ShXReg = MIRBuilder.buildShl(Ty, ShX1Reg, InvShAmtReg).getReg(0);
      ShYReg = MIRBuilder.buildLShr(Ty, YReg, ShAmtReg).getReg(0);
    }

    MIRBuilder.buildOr(DstReg, ShXReg, ShYReg);
    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }
  if (Ty == LLT::scalar(8))
    if (auto Amt = getIConstantVRegValWithLookThrough(AmtReg, MRI))
      return LegalizerHelper::AlreadyLegal;

  unsigned FwdShiftOpc = G_SHL;
  unsigned RevShiftOpc = G_LSHR;
  if (Opc == G_FSHR || Opc == G_ROTR) {
    std::swap(FwdReg, RevReg);
    std::swap(FwdShiftOpc, RevShiftOpc);
  }

  auto MaskI = MIRBuilder.buildConstant(Ty, Ty.getSizeInBits() - 1);
  auto FwdAmtI = MIRBuilder.buildAnd(Ty, AmtReg, MaskI);
  auto FwdI = MIRBuilder.buildInstr(FwdShiftOpc, {Ty}, {FwdReg, FwdAmtI});
  auto RevAmtI = MIRBuilder.buildAnd(
      Ty, MIRBuilder.buildSub(Ty, MIRBuilder.buildConstant(Ty, 0), AmtReg),
      MaskI);
  auto RevI = MIRBuilder.buildInstr(RevShiftOpc, {Ty}, {RevReg, RevAmtI});
  MIRBuilder.buildOr(DstReg, FwdI, RevI);
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeCompare(LegalizerHelper &Helper, MachineInstr &MI,
                                  LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
  Register DstReg = MI.getOperand(0).getReg();
  auto Pred = CmpInst::Predicate(MI.getOperand(1).getPredicate());
  Register LHSReg = MI.getOperand(2).getReg();
  Register RHSReg = MI.getOperand(3).getReg();
  LLT OpTy = MRI.getType(LHSReg);
  unsigned OpSize = OpTy.getSizeInBits();
  assert(MRI.getType(DstReg) == LLT::scalar(1) && !OpTy.isVector() &&
         MRI.getType(RHSReg) == OpTy && "Unexpected type");

  Type *Ty;
  RTLIB::Libcall Libcall;
  bool IsSigned, IsSwapped, IsConst;
  Z80::CondCode CC =
      Z80::GetBranchConditionForPredicate(Pred, IsSigned, IsSwapped, IsConst);
  if (IsSwapped)
    std::swap(LHSReg, RHSReg);
  auto &Ctx = MIRBuilder.getMF().getFunction().getContext();
  bool ZeroRHS = false;
  if (MI.getOpcode() == G_ICMP) {
    Ty = IntegerType::get(Ctx, OpSize);
    if (auto C = getIConstantVRegVal(RHSReg, MRI))
      ZeroRHS = *C == 0;
    switch (OpSize) {
    case 32:
      Libcall = ZeroRHS    ? RTLIB::CMP_I32_0
                : IsSigned ? RTLIB::SCMP_I32
                           : RTLIB::CMP_I32;
      break;
    case 48:
      Libcall = ZeroRHS    ? RTLIB::CMP_I48_0
                : IsSigned ? RTLIB::SCMP_I48
                           : RTLIB::CMP_I48;
      break;
    case 64:
      Libcall = ZeroRHS    ? RTLIB::CMP_I64_0
                : IsSigned ? RTLIB::SCMP_I64
                           : RTLIB::CMP_I64;
      break;
    default:
      llvm_unreachable("Unexpected type");
    }
  } else {
    assert(MI.getOpcode() == G_FCMP && "Unexpected opcode");
    assert(OpTy.isScalar() && "Unexpected type");
    switch (OpSize) {
    case 32:
      Ty = Type::getFloatTy(Ctx);
      Libcall = RTLIB::CMP_F32;
      break;
    case 64:
      Ty = Type::getDoubleTy(Ctx);
      Libcall = RTLIB::CMP_F64;
      break;
    default:
      llvm_unreachable("Unexpected type");
    }
  }
  if (!IsConst) {
    LLT s8 = LLT::scalar(8);
    Type *Int8Ty = Type::getInt8Ty(Ctx);
    Register FlagsReg = MRI.createGenericVirtualRegister(s8);
    CallLowering::ArgInfo FlagsArg(FlagsReg, Int8Ty,
                                   CallLowering::ArgInfo::NoArgIndex);
    CallLowering::ArgInfo Args[2] = {{LHSReg, Ty, 0}, {RHSReg, Ty, 1}};
    auto Result = createLibcall(MIRBuilder, Libcall, FlagsArg,
                                ArrayRef(Args, 2 - ZeroRHS), LocObserver,
                                &MI);
    if (Result != LegalizerHelper::Legalized)
      return Result;
    MIRBuilder.buildCopy(Register(Z80::F), FlagsReg);
    if (IsSigned && !ZeroRHS)
      Subtarget.getCallLowering()->buildSCMP(MIRBuilder);
  } else
    MIRBuilder.buildInstr(Z80::RCF);
  MIRBuilder.buildInstr(Z80::SetCC, {DstReg}, {int64_t(CC)});
  MRI.setRegClass(DstReg, &Z80::R8RegClass);
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFixedMultiply(LegalizerHelper &Helper,
                                        MachineInstr &MI) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  unsigned Opc = MI.getOpcode();
  bool Signed = Opc == G_SMULFIX || Opc == G_SMULFIXSAT;
  bool Sat = Opc == G_SMULFIXSAT || Opc == G_UMULFIXSAT;
  assert((Signed || Sat || Opc == G_UMULFIX) && "Unexpected opcode");

  Register DstReg = MI.getOperand(0).getReg();
  unsigned OpSize = MRI.getType(DstReg).getSizeInBits();
  Register LHSReg = MI.getOperand(1).getReg();
  Register RHSReg = MI.getOperand(2).getReg();
  uint64_t Shift = MI.getOperand(3).getImm();
  unsigned WideSize = OpSize * 2;
  LLT WideTy = LLT::scalar(WideSize);

  if (Shift >= WideSize)
    return LegalizerHelper::UnableToLegalize;

  Register WideDstReg =
      MIRBuilder
          .buildInstr(Signed ? G_ASHR : G_LSHR, {WideTy},
                      {MIRBuilder.buildMul(
                           WideTy,
                           MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT,
                                                 {WideTy}, {LHSReg}),
                           MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT,
                                                 {WideTy}, {RHSReg})),
                       MIRBuilder.buildConstant(WideTy, Shift)})
          .getReg(0);
  if (Sat) {
    unsigned MinOpc;
    APInt Max;
    if (Signed) {
      WideDstReg =
          MIRBuilder
              .buildSMax(
                  WideTy, WideDstReg,
                  MIRBuilder.buildConstant(
                      WideTy, APInt::getSignedMinValue(OpSize).sext(WideSize)))
              .getReg(0);
      MinOpc = G_SMIN;
      Max = APInt::getSignedMaxValue(OpSize).sext(WideSize);
    } else {
      MinOpc = G_UMIN;
      Max = APInt::getMaxValue(OpSize).zext(WideSize);
    }
    WideDstReg =
        MIRBuilder
            .buildInstr(MinOpc, {WideTy},
                        {WideDstReg, MIRBuilder.buildConstant(WideTy, Max)})
            .getReg(0);
  }
  MIRBuilder.buildTrunc(DstReg, WideDstReg);

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFixedDivide(LegalizerHelper &Helper,
                                      MachineInstr &MI) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  unsigned Opc = MI.getOpcode();
  bool Signed = Opc == G_SDIVFIX || Opc == G_SDIVFIXSAT;
  bool Sat = Opc == G_SDIVFIXSAT || Opc == G_UDIVFIXSAT;
  assert((Signed || Sat || Opc == G_UDIVFIX) && "Unexpected opcode");

  Register DstReg = MI.getOperand(0).getReg();
  LLT OpTy = MRI.getType(DstReg);
  unsigned OpSize = OpTy.getSizeInBits();
  Register LHSReg = MI.getOperand(1).getReg();
  Register RHSReg = MI.getOperand(2).getReg();
  uint64_t Shift = MI.getOperand(3).getImm();
  unsigned WideSize = OpSize * 2;
  LLT WideTy = LLT::scalar(WideSize);

  if (Shift > 0 && Shift <= OpSize / 2 && WideSize > 64) {
    // FIXME: accuracy
    auto DivRemI = MIRBuilder.buildInstr(Signed ? G_SDIVREM : G_UDIVREM,
                                         {OpTy, OpTy}, {LHSReg, RHSReg});
    Register PosReg = DivRemI.getReg(1);
    if (Signed)
      PosReg = MIRBuilder
                   .buildXor(OpTy, PosReg,
                             MIRBuilder.buildAShr(
                                 OpTy, PosReg,
                                 MIRBuilder.buildConstant(OpTy, OpSize - 1)))
                   .getReg(0);
    Register ScaleReg =
        MIRBuilder
            .buildSelect(
                OpTy,
                MIRBuilder.buildICmp(
                    CmpInst::ICMP_ULT, LLT::scalar(1), PosReg,
                    MIRBuilder.buildConstant(
                        OpTy, APInt::getOneBitSet(OpSize, Shift - Signed))),
                MIRBuilder.buildConstant(OpTy, Shift - Signed),
                MIRBuilder.buildAdd(
                    OpTy,
                    MIRBuilder.buildInstr(G_CTLZ_ZERO_UNDEF, {OpTy}, {PosReg}),
                    MIRBuilder.buildConstant(OpTy, -Signed)))
            .getReg(0);
    Register ShiftReg = MIRBuilder.buildConstant(OpTy, Shift).getReg(0);
    Register InvScaleReg =
        MIRBuilder.buildSub(OpTy, ShiftReg, ScaleReg).getReg(0);
    Register OneReg = MIRBuilder.buildConstant(OpTy, 1).getReg(0);
    MIRBuilder.buildAdd(
        DstReg, MIRBuilder.buildShl(OpTy, DivRemI.getReg(0), ShiftReg),
        MIRBuilder.buildInstr(
            Signed ? G_ASHR : G_LSHR, {OpTy},
            {MIRBuilder.buildInstr(
                 Signed ? G_SDIV : G_UDIV, {OpTy},
                 {MIRBuilder.buildShl(OpTy, DivRemI.getReg(1), ScaleReg),
                  MIRBuilder.buildAdd(
                      OpTy, RHSReg,
                      MIRBuilder.buildLShr(
                          OpTy, MIRBuilder.buildShl(OpTy, OneReg, InvScaleReg),
                          OneReg))}),
             InvScaleReg}));
    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  if (Shift >= WideSize)
    return LegalizerHelper::UnableToLegalize;

  Register WideDstReg =
      MIRBuilder
          .buildInstr(Signed ? G_SDIV : G_UDIV, {WideTy},
                      {MIRBuilder.buildShl(
                           WideTy,
                           MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT,
                                                 {WideTy}, {LHSReg}),
                           MIRBuilder.buildConstant(WideTy, Shift)),
                       MIRBuilder.buildInstr(Signed ? G_SEXT : G_ZEXT, {WideTy},
                                             {RHSReg})})
          .getReg(0);
  if (Sat) {
    unsigned MinOpc;
    APInt Max;
    if (Signed) {
      WideDstReg =
          MIRBuilder
              .buildSMax(
                  WideTy, WideDstReg,
                  MIRBuilder.buildConstant(
                      WideTy, APInt::getSignedMinValue(OpSize).sext(WideSize)))
              .getReg(0);
      MinOpc = G_SMIN;
      Max = APInt::getSignedMaxValue(OpSize).sext(WideSize);
    } else {
      MinOpc = G_UMIN;
      Max = APInt::getMaxValue(OpSize).zext(WideSize);
    }
    WideDstReg =
        MIRBuilder
            .buildInstr(MinOpc, {WideTy},
                        {WideDstReg, MIRBuilder.buildConstant(WideTy, Max)})
            .getReg(0);
  }
  MIRBuilder.buildTrunc(DstReg, WideDstReg);

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeMultiplyWithOverflow(
    LegalizerHelper &Helper, MachineInstr &MI,
    LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  unsigned Opc = MI.getOpcode();
  assert((Opc == G_UMULO || Opc == G_SMULO) && "Unexpected opcode");

  Register MulReg = MI.getOperand(0).getReg();
  Register OverflowReg = MI.getOperand(1).getReg();
  LLT Ty = MRI.getType(MulReg);

  Register LHSReg = MI.getOperand(2).getReg();
  Register RHSReg = MI.getOperand(3).getReg();

  if (Opc == G_UMULO) {
    MIRBuilder.buildMul(MulReg, LHSReg, RHSReg);

    auto One = MIRBuilder.buildConstant(Ty, 1);
    auto Max =
        MIRBuilder.buildConstant(Ty, APInt::getMaxValue(Ty.getSizeInBits()));
    MIRBuilder.buildICmp(
        CmpInst::ICMP_UGT, OverflowReg, LHSReg,
        MIRBuilder.buildInstr(G_UDIV, {Ty},
                              {Max, MIRBuilder.buildUMax(Ty, RHSReg, One)}));
  } else {
    // signed multiply with overflow:
    // - i64 uses the standard compiler-rt helper (__mulodi4) via RTLIB::MULO_I64
    // - smaller sizes widen to i32 and use __mulosi4, then check truncation
    //   for the original size
    const unsigned Size = Ty.getSizeInBits();
    LLVMContext &Ctx = MIRBuilder.getMF().getFunction().getContext();

    RTLIB::Libcall Libcall;
    unsigned WideBits;
    if (Size > 32) {
      if (Size != 64)
        return LegalizerHelper::UnableToLegalize;
      Libcall = RTLIB::MULO_I64;
      WideBits = 64;
    } else {
      Libcall = RTLIB::MULO_I32;
      WideBits = 32;
    }

    LLT WideTy = LLT::scalar(WideBits);
    Type *WideIRTy = IntegerType::get(Ctx, WideBits);
    Type *PtrIRTy = PointerType::get(Ctx, 0);

    // __mul{o}si4/di4 write the overflow flag through an int*
    MachineFunction &MF = MIRBuilder.getMF();
    MachineFrameInfo &MFI = MF.getFrameInfo();
    int OFI = MFI.CreateStackObject(4, Align(1), /*IsSpillSlot=*/false);

    const unsigned PtrBits = TM.getPointerSizeInBits(0);
    Register OFAddr = MIRBuilder
                          .buildFrameIndex(LLT::pointer(0, PtrBits), OFI)
                          .getReg(0);

    Register WideMulReg =
        (Size == WideBits) ? MulReg : MRI.createGenericVirtualRegister(WideTy);
    auto buildSignedWidenForLibcall = [&](Register SrcReg) {
      if (Size == WideBits)
        return SrcReg;

      // On v18, i16->i32 widening via plain G_SEXT can produce duplicate low-part
      // COPY defs after legalization/regbankselect, which then trips ISel cleanup.
      if (Size * 2 == WideBits) {
        Register ShiftAmt =
            MIRBuilder.buildConstant(Ty, Size - 1).getReg(0);
        Register High = MIRBuilder.buildAShr(Ty, SrcReg, ShiftAmt).getReg(0);
        return MIRBuilder.buildMergeLikeInstr(WideTy, {SrcReg, High}).getReg(0);
      }

      return MIRBuilder.buildSExt(WideTy, SrcReg).getReg(0);
    };

    Register WideLHS = buildSignedWidenForLibcall(LHSReg);
    Register WideRHS = buildSignedWidenForLibcall(RHSReg);

    auto CallResult = createLibcall(
        MIRBuilder, Libcall, {WideMulReg, WideIRTy, 0},
        {{WideLHS, WideIRTy, 0}, {WideRHS, WideIRTy, 1}, {OFAddr, PtrIRTy, 2}},
        LocObserver, &MI);
    if (CallResult != LegalizerHelper::Legalized)
      return CallResult;

    // Load `int overflow` and convert to i1.
    MachinePointerInfo MPO = MachinePointerInfo::getFixedStack(MF, OFI);
    auto *MMO = MF.getMachineMemOperand(MPO, MachineMemOperand::MOLoad, 4,
                                        Align(1));
    Register OF32 = MRI.createGenericVirtualRegister(LLT::scalar(32));
    MIRBuilder.buildLoad(OF32, OFAddr, *MMO);
    Register OFBool =
        MIRBuilder
            .buildICmp(CmpInst::ICMP_NE, LLT::scalar(1), OF32,
                       MIRBuilder.buildConstant(LLT::scalar(32), 0))
            .getReg(0);

    if (Size == WideBits) {
      MIRBuilder.buildCopy(OverflowReg, OFBool);
    } else {
      // truncate back to the original size and compute additional overflow due
      // to truncation (i32 product doesnt fit in i8/i16/i24).
      MIRBuilder.buildTrunc(MulReg, WideMulReg);
      Register ResExt =
          MIRBuilder.buildSExt(WideTy, MulReg).getReg(0);
      Register TruncOverflow =
          MIRBuilder
              .buildICmp(CmpInst::ICMP_NE, LLT::scalar(1), ResExt, WideMulReg)
              .getReg(0);

      LLT s8 = LLT::scalar(8);
      Register OF8 = MIRBuilder.buildZExt(s8, OFBool).getReg(0);
      Register TO8 = MIRBuilder.buildZExt(s8, TruncOverflow).getReg(0);
      Register Any8 = MIRBuilder.buildOr(s8, OF8, TO8).getReg(0);
      MIRBuilder.buildICmp(CmpInst::ICMP_NE, OverflowReg, Any8,
                           MIRBuilder.buildConstant(s8, 0));
    }

    MI.eraseFromParent();
    return LegalizerHelper::Legalized;
  }

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFCanonicalize(LegalizerHelper &Helper,
                                        MachineInstr &MI) const {
  Helper.Observer.changingInstr(MI);
  MI.setDesc(Helper.MIRBuilder.getTII().get(COPY));
  Helper.Observer.changedInstr(MI);
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFFrexp(LegalizerHelper &Helper, MachineInstr &MI,
                                 LostDebugLocObserver &LocObserver) const {
  assert(MI.getOpcode() == G_FFREXP && "Unexpected opcode");
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  Register DstMantReg = MI.getOperand(0).getReg();
  Register DstExpReg = MI.getOperand(1).getReg();
  Register SrcReg = MI.getOperand(2).getReg();

  LLT MantTy = MRI.getType(DstMantReg);
  LLT ExpTy = MRI.getType(DstExpReg);
  if (ExpTy != LLT::scalar(24))
    return LegalizerHelper::UnableToLegalize;

  LLVMContext &Ctx = MIRBuilder.getMF().getFunction().getContext();
  Type *MantIRTy = nullptr;
  RTLIB::Libcall Libcall;
  if (MantTy == LLT::scalar(32)) {
    MantIRTy = Type::getFloatTy(Ctx);
    Libcall = RTLIB::FREXP_F32;
  } else if (MantTy == LLT::scalar(64)) {
    MantIRTy = Type::getDoubleTy(Ctx);
    Libcall = RTLIB::FREXP_F64;
  } else {
    return LegalizerHelper::UnableToLegalize;
  }
  Type *PtrIRTy = PointerType::get(Ctx, 0);

  MachineFunction &MF = MIRBuilder.getMF();
  MachineFrameInfo &MFI = MF.getFrameInfo();
  int ExpFI = MFI.CreateStackObject(/*Size=*/3, Align(1),
                                    /*IsSpillSlot=*/false);
  Register ExpAddr =
      MIRBuilder
          .buildFrameIndex(LLT::pointer(0, TM.getPointerSizeInBits(0)), ExpFI)
          .getReg(0);

  auto CallResult =
      createLibcall(MIRBuilder, Libcall, {DstMantReg, MantIRTy, 0},
                    {{SrcReg, MantIRTy, 0}, {ExpAddr, PtrIRTy, 1}},
                    LocObserver, &MI);
  if (CallResult != LegalizerHelper::Legalized)
    return CallResult;

  MachinePointerInfo MPO = MachinePointerInfo::getFixedStack(MF, ExpFI);
  auto *MMO = MF.getMachineMemOperand(MPO, MachineMemOperand::MOLoad, 3,
                                      Align(1));
  MIRBuilder.buildLoad(DstExpReg, ExpAddr, *MMO);

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeFLdexp(LegalizerHelper &Helper, MachineInstr &MI,
                                 LostDebugLocObserver &LocObserver) const {
  assert(MI.getOpcode() == G_FLDEXP && "Unexpected opcode");
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  Register DstReg = MI.getOperand(0).getReg();
  Register SrcReg = MI.getOperand(1).getReg();
  Register ExpReg = MI.getOperand(2).getReg();

  LLT DstTy = MRI.getType(DstReg);
  LLT ExpTy = MRI.getType(ExpReg);
  if (ExpTy != LLT::scalar(24))
    return LegalizerHelper::UnableToLegalize;

  LLVMContext &Ctx = MIRBuilder.getMF().getFunction().getContext();
  Type *FloatTy = nullptr;
  RTLIB::Libcall Libcall;
  if (DstTy == LLT::scalar(32)) {
    FloatTy = Type::getFloatTy(Ctx);
    Libcall = RTLIB::LDEXP_F32;
  } else if (DstTy == LLT::scalar(64)) {
    FloatTy = Type::getDoubleTy(Ctx);
    Libcall = RTLIB::LDEXP_F64;
  } else {
    return LegalizerHelper::UnableToLegalize;
  }
  Type *ExpIRTy = IntegerType::get(Ctx, 24);

  auto CallResult =
      createLibcall(MIRBuilder, Libcall, {DstReg, FloatTy, 0},
                    {{SrcReg, FloatTy, 0}, {ExpReg, ExpIRTy, 1}}, LocObserver,
                    &MI);
  if (CallResult != LegalizerHelper::Legalized)
    return CallResult;

  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeCtz(LegalizerHelper &Helper, MachineInstr &MI,
                              LostDebugLocObserver &LocObserver) const {
  assert((MI.getOpcode() == G_CTLZ || MI.getOpcode() == G_CTTZ) &&
         "Unexpected opcode");
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
  auto &Ctx = MIRBuilder.getMF().getFunction().getContext();

  Register DstReg = MI.getOperand(0).getReg();
  LLT DstTy = MRI.getType(DstReg);
  unsigned DstSize = DstTy.getSizeInBits();
  Register SrcReg = MI.getOperand(1).getReg();
  LLT SrcTy = MRI.getType(SrcReg);
  unsigned SrcSize = SrcTy.getSizeInBits();

  if (DstTy != LLT::scalar(8) || !SrcTy.isScalar())
    return LegalizerHelper::UnableToLegalize;

  RTLIB::Libcall Libcall;
  bool Leading = MI.getOpcode() == G_CTLZ;
  switch (SrcSize) {
  default: return LegalizerHelper::UnableToLegalize;
  case  8: Libcall = Leading ? RTLIB::CTLZ_I8  : RTLIB::CTTZ_I8;  break;
  case 16: Libcall = Leading ? RTLIB::CTLZ_I16 : RTLIB::CTTZ_I16; break;
  case 24: Libcall = Leading ? RTLIB::CTLZ_I24 : RTLIB::CTTZ_I24; break;
  case 32: Libcall = Leading ? RTLIB::CTLZ_I32 : RTLIB::CTTZ_I32; break;
  case 48: Libcall = Leading ? RTLIB::CTLZ_I48 : RTLIB::CTTZ_I48; break;
  case 64: Libcall = Leading ? RTLIB::CTLZ_I64 : RTLIB::CTTZ_I64; break;
  }
  auto Result = createLibcall(
      MIRBuilder, Libcall, {DstReg, IntegerType::get(Ctx, DstSize), 0},
      {{SrcReg, IntegerType::get(Ctx, SrcSize), 0}}, LocObserver, &MI);
  MI.eraseFromParent();
  return Result;
}

LegalizerHelper::LegalizeResult Z80LegalizerInfo::legalizeMemIntrinsic(
    LegalizerHelper &Helper, MachineInstr &MI,
    LostDebugLocObserver &LocObserver) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
  MachineFunction &MF = MIRBuilder.getMF();
  const DataLayout &DL = MF.getDataLayout();
  bool Is24Bit = Subtarget.is24Bit();

  unsigned Opc = MI.getOpcode();
  assert((Opc == G_MEMCPY || Opc == G_MEMCPY_INLINE || Opc == G_MEMMOVE ||
          Opc == G_MEMSET || Opc == G_BZERO) &&
         "Unexpected opcode");

  auto MOI = MI.operands_begin();

  Register DstReg = MOI->getReg();
  LLT DstTy = MRI.getType(DstReg);

  Register SrcReg = Opc != G_BZERO
                        ? (++MOI)->getReg()
                        : MIRBuilder.buildConstant(LLT::scalar(8), 0).getReg(0);
  LLT SrcTy = MRI.getType(SrcReg);

  Register LenReg = (++MOI)->getReg();
  LLT LenTy = LLT::scalar(DL.getIndexSizeInBits(DstTy.getAddressSpace()));
  LenReg = MIRBuilder.buildZExtOrTrunc(LenTy, LenReg).getReg(0);

  // We need to make sure the number of bytes is non-zero for this lowering to
  // be correct.  Since we only need to lower constant-length intrinsics for
  // now, just support those.
  if (Opc == G_MEMCPY_INLINE || !MF.getFunction().hasOptNone()) {
    if (auto ConstLen = getIConstantVRegValWithLookThrough(LenReg, MRI)) {
      // Doing something with zero bytes is a noop anyway.
      if (!ConstLen->Value) {
        MI.eraseFromParent();
        return LegalizerHelper::Legalized;
      }
      // Lowering memmove generates a lot of code...
      if (!MF.getFunction().hasOptSize() || Opc != G_MEMMOVE) {
        MachineMemOperand *StoreMMO = MI.memoperands().front();
        MachineMemOperand *LoadMMO;

        if (Opc == G_MEMSET) {
          // Store the first byte.
          MIRBuilder.buildStore(SrcReg, DstReg, *StoreMMO);

          // Use stores if 4 bytes or less
          if (ConstLen->Value.ule(4)) {
            for (unsigned int Offset = 1; ConstLen->Value.ugt(Offset);
                 ++Offset) {
              auto OffConst = MIRBuilder.buildConstant(LenTy, Offset);
              auto AddrReg = MIRBuilder.buildPtrAdd(DstTy, DstReg, OffConst);
              MIRBuilder.buildStore(
                  SrcReg, AddrReg,
                  *MF.getMachineMemOperand(StoreMMO, Offset, LLT::scalar(8)));
            }
            MI.eraseFromParent();
            return LegalizerHelper::Legalized;
          }

          // Read starting at the stored byte.
          SrcTy = DstTy;
          SrcReg = DstReg;
          LoadMMO = MF.getMachineMemOperand(
              StoreMMO->getPointerInfo(),
              (StoreMMO->getFlags() & ~MachineMemOperand::MOStore) |
                  MachineMemOperand::MOLoad,
              StoreMMO->getMemoryType(), StoreMMO->getAlign(),
              StoreMMO->getAAInfo(), StoreMMO->getRanges(),
              StoreMMO->getSyncScopeID(), StoreMMO->getSuccessOrdering(),
              StoreMMO->getFailureOrdering());
          // Write starting at the following byte.
          auto One = MIRBuilder.buildConstant(LenTy, 1);
          DstReg = MIRBuilder.buildPtrAdd(DstTy, DstReg, One).getReg(0);
          // Copy one less byte.
          LenReg = MIRBuilder.buildConstant(LenTy, --ConstLen->Value).getReg(0);
          // Now it's just an ldir.
        } else
          LoadMMO = MI.memoperands().back();

        Register DE = Is24Bit ? Z80::UDE : Z80::DE;
        Register HL = Is24Bit ? Z80::UHL : Z80::HL;
        Register BC = Is24Bit ? Z80::UBC : Z80::BC;
        auto ConstSrc = getIConstantVRegValWithLookThrough(SrcReg, MRI);
        auto ConstDst = getIConstantVRegValWithLookThrough(DstReg, MRI);
        bool ConstAddr = ConstSrc && ConstDst;
        if (!MI.hasOrderedMemoryRef() && ConstAddr &&
            ConstSrc->Value == ConstDst->Value) {
          MI.eraseFromParent();
          return LegalizerHelper::Legalized;
        }
        if (Opc == G_MEMMOVE && !ConstAddr) {
          // the LDR24/LDR16 pseudo instruction handles the comparison
          // internally to amke sure its always uses sbc hl, de
          // rather than potentially sbc hl, iy (invalid instruction) if DstReg
          // happens to be allocated to IY
          MIRBuilder
              .buildInstr(Is24Bit ? Z80::LDR24 : Z80::LDR16, {},
                          {DstReg, SrcReg, LenReg})
              .cloneMemRefs(MI);
        } else if (Opc != G_MEMMOVE ||
                   (ConstAddr && (ConstDst->Value.ule(ConstSrc->Value) ||
                                  (ConstDst->Value - ConstSrc->Value)
                                      .uge(ConstLen->Value)))) {
          // Use loads/stores if 4 bytes or less
          if (ConstLen->Value.ule(4)) {
            for (unsigned int Offset = 0; ConstLen->Value.ugt(Offset);
                 ++Offset) {
              auto OffConst = MIRBuilder.buildConstant(LenTy, Offset);
              auto SrcAddrI = MIRBuilder.buildPtrAdd(SrcTy, SrcReg, OffConst);
              auto LoadReg = MIRBuilder.buildLoad(
                  LLT::scalar(8), SrcAddrI,
                  *MF.getMachineMemOperand(LoadMMO, Offset, LLT::scalar(8)));
              auto DstAddrI = MIRBuilder.buildPtrAdd(DstTy, DstReg, OffConst);
              MIRBuilder.buildStore(
                  LoadReg, DstAddrI,
                  *MF.getMachineMemOperand(StoreMMO, Offset, LLT::scalar(8)));
            }
          } else {
            MIRBuilder.buildCopy(DE, DstReg);
            MIRBuilder.buildCopy(HL, SrcReg);
            MIRBuilder.buildCopy(BC, LenReg);
            MIRBuilder.buildInstr(Is24Bit ? Z80::LDIR24 : Z80::LDIR16)
                .cloneMemRefs(MI);
          }
        } else {
          auto LenMinusOne =
              MIRBuilder.buildConstant(LenTy, ConstLen->Value - 1);
          MIRBuilder.buildCopy(
              DE, MIRBuilder.buildPtrAdd(DstTy, DstReg, LenMinusOne));
          MIRBuilder.buildCopy(
              HL, MIRBuilder.buildPtrAdd(SrcTy, SrcReg, LenMinusOne));
          MIRBuilder.buildCopy(BC, LenReg);
          MIRBuilder.buildInstr(Is24Bit ? Z80::LDDR24 : Z80::LDDR16)
              .cloneMemRefs(MI);
        }
        MI.eraseFromParent();
        return LegalizerHelper::Legalized;
      }
    }
  }

  MOI->setReg(LenReg);
  auto Result = createMemLibcall(MIRBuilder, MRI, MI, LocObserver);
  MI.eraseFromParent();
  return Result;
}

bool Z80LegalizerInfo::legalizeIntrinsic(LegalizerHelper &Helper,
                                         MachineInstr &MI) const {
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineFunction &MF = MIRBuilder.getMF();
  auto &Ctx = MF.getFunction().getContext();
  auto &CLI = *MF.getSubtarget().getCallLowering();

  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  case Intrinsic::trap: {
    CallLowering::CallLoweringInfo Info;
    Info.CallConv = CallingConv::C;
    Info.Callee = MachineOperand::CreateES("abort");
    Info.OrigRet = CallLowering::ArgInfo{{}, Type::getVoidTy(Ctx), 0};
    if (!CLI.lowerCall(MIRBuilder, Info))
      return false;
    break;
  }
  case Intrinsic::vacopy: {
    const MachineRegisterInfo &MRI = *MIRBuilder.getMRI();
    const MachineFrameInfo &MFI = MF.getFrameInfo();
    const DataLayout &DL = MF.getDataLayout();

    Register DstReg = MI.getOperand(1).getReg();
    MachineInstr *DstMI = MRI.getVRegDef(DstReg);
    MachinePointerInfo DstMPI;
    Align DstAlign = DL.getPointerABIAlignment(0);
    if (DstMI && DstMI->getOpcode() == G_FRAME_INDEX) {
      int FI = DstMI->getOperand(1).getIndex();
      DstMPI = MachinePointerInfo::getFixedStack(MF, FI);
      DstAlign = MFI.getObjectAlign(FI);
    }

    Register SrcReg = MI.getOperand(2).getReg();
    MachineInstr *SrcMI = MRI.getVRegDef(SrcReg);
    MachinePointerInfo SrcMPI;
    Align SrcAlign = DL.getPointerABIAlignment(0);
    if (SrcMI && SrcMI->getOpcode() == G_FRAME_INDEX) {
      int FI = SrcMI->getOperand(1).getIndex();
      SrcMPI = MachinePointerInfo::getFixedStack(MF, FI);
      SrcAlign = MFI.getObjectAlign(FI);
    }

    LLT p0 = LLT::pointer(0, TM.getPointerSizeInBits(0));
    MIRBuilder.buildStore(MIRBuilder.buildLoad(p0, SrcReg, SrcMPI, SrcAlign),
                          DstReg, DstMPI, DstAlign);
    break;
  }
  default:
    return false;
  }

  MI.eraseFromParent();
  return true;
}

LegalizerHelper::LegalizeResult
Z80LegalizerInfo::legalizeMergeValues(LegalizerHelper &Helper,
                                      MachineInstr &MI) const {
  // this handles G_MERGE_VALUES with s1 source operands
  // example: %dst:_(s8) = G_MERGE_VALUES %0:_(s1), %1:_(s1), ...
  // they're expanded into zero extends, shifts, and adds,
  // in a way that minimizes the total number of bits shifted
  //   %ext7 = G_ANYEXT %7 -> s8
  //   %shl6 = G_SHL %ext7, 1
  //   %ext6 = G_ZEXT %6 -> s8
  //   %add6 = G_ADD %shl6, %ext6
  //   %shl5 = G_SHL %add6, 1
  //   ... and so on
  // any constant operands are skipped during this process and
  // added at the end
  MachineIRBuilder &MIRBuilder = Helper.MIRBuilder;
  MachineRegisterInfo &MRI = *MIRBuilder.getMRI();

  Register DstReg = MI.getOperand(0).getReg();
  LLT DstTy = MRI.getType(DstReg);

  // iterate sources in reverse to propagate const/undef
  bool AllUndef = true;
  unsigned I, BitCount = MI.getNumOperands() - 1;
  auto ConstantBits = APInt::getZero(BitCount);
  for (I = BitCount; I > 0; I--) {
    MachineOperand SrcOperand = MI.getOperand(I);
    if (SrcOperand.isUndef())
      continue;
    if (auto ConstSrc =
            getIConstantVRegValWithLookThrough(SrcOperand.getReg(), MRI)) {
      AllUndef = false;
      if (!ConstSrc->Value.isZero())
        ConstantBits.setBit(I - 1);
    } else {
      break;
    }
  }

  MachineInstrBuilder Result;
  if (I == 0) {
    // if no non-constant register was found, set the result directly
    if (AllUndef)
      Result = MIRBuilder.buildUndef(DstTy);
    else
      Result = MIRBuilder.buildConstant(DstTy, ConstantBits);
  } else {
    // extend the highest non-constant register
    Register SrcReg = MI.getOperand(I).getReg();
    if (AllUndef)
      Result = MIRBuilder.buildAnyExt(DstTy, SrcReg);
    else
      Result = MIRBuilder.buildZExt(DstTy, SrcReg);

    // for the remaining registers, shift the result left and add them in
    // possible future improvement: fold to carry flag and rotate left
    unsigned ShiftAmt = 0;
    while (--I > 0) {
      ShiftAmt++;
      MachineOperand SrcOperand = MI.getOperand(I);
      if (SrcOperand.isUndef())
        continue;
      Register SrcReg = SrcOperand.getReg();
      if (auto ConstSrc = getIConstantVRegValWithLookThrough(SrcReg, MRI)) {
        if (!ConstSrc->Value.isZero())
          ConstantBits.setBit(I - 1);
        continue;
      }

      // shift left by the number of iterations since the last shift
      auto ShiftCst = MIRBuilder.buildConstant(DstTy, ShiftAmt);
      Result = MIRBuilder.buildShl(DstTy, Result, ShiftCst);
      ShiftAmt = 0;

      // zero extend the s1 to the destination type
      auto ZExt = MIRBuilder.buildZExt(DstTy, SrcReg);

      // add into the accumulated result
      Result = MIRBuilder.buildAdd(
          DstTy, Result, ZExt, MachineInstr::NoUWrap | MachineInstr::NoSWrap);
    }

    // do any leftover shift
    if (ShiftAmt) {
      auto ShiftCst = MIRBuilder.buildConstant(DstTy, ShiftAmt);
      Result = MIRBuilder.buildShl(DstTy, Result, ShiftCst);
    }

    // finally, combine with constant bits
    if (!ConstantBits.isZero()) {
      auto Constant = MIRBuilder.buildConstant(DstTy, ConstantBits);
      Result =
          MIRBuilder.buildAdd(DstTy, Result, Constant,
                              MachineInstr::NoUWrap | MachineInstr::NoSWrap);
    }
  }

  MIRBuilder.buildCopy(DstReg, Result);
  MI.eraseFromParent();
  return LegalizerHelper::Legalized;
}
